CREATE TABLE IF NOT EXISTS store_services (id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS store_orders (id TEXT PRIMARY KEY, access_hash TEXT NOT NULL, service_id TEXT NOT NULL, service_title TEXT NOT NULL, name TEXT NOT NULL, contact TEXT NOT NULL, description TEXT NOT NULL, budget INTEGER NOT NULL, deadline TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', amount INTEGER, payment_url TEXT, payment_ref TEXT, paid INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS store_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, action TEXT NOT NULL, created INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS store_payment_ref ON store_orders(payment_ref) WHERE payment_ref IS NOT NULL AND payment_ref!='';
CREATE TABLE IF NOT EXISTS store_limits (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires INTEGER NOT NULL);
